#!/bin/sh
# layer-2 load audit -- cpp -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_cpp.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_cpp
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_cpp.txt
: > "$OUT"
echo "=== layer-2 load audit -- cpp ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! command -v g++ >/dev/null 2>&1; then
  echo "cpp: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.std::monostate.null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > main.cpp <<'L2_SRC_EOF'
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <deque>
#include <iostream>
#include <limits>
#include <list>
#include <map>
#include <memory>
#include <optional>
#include <set>
#include <sstream>
#include <string>
#include <tuple>
#include <unordered_map>
#include <variant>
#include <vector>
#include <variant>
#include <string>

int main() {
  std::monostate v = std::monostate{};
  std::cout << "nothing.std::monostate.null" << "|" << (std::string("monostate")) << std::endl;
  return 0;
}
L2_SRC_EOF
V=ok
if ! timeout 180 g++ -O0 -std=c++17 -o prog main.cpp > build.out 2> build.err; then V="<compile-error>"; fi
if [ "$V" = ok ]; then
  if timeout 30 ./prog > run.out 2> run.err; then :; else
    V="<aborted>"
  fi
  grep -F "nothing.std::monostate.null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.std::monostate.null|" "$OUT" || echo "nothing.std::monostate.null|$V" >> "$OUT"

